-- ----------------------------
-- Table structure for excel_template
-- ----------------------------
DROP TABLE IF EXISTS `excel_template`;
CREATE TABLE `excel_template`  (
  `id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键ID',
  `template_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板编码(唯一标识)',
  `template_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板名称',
  `column_config` json NOT NULL COMMENT '列配置信息[{\"fieldName\":\"姓名\",\"excelHeader\":\"姓名\",\"dataType\":\"STRING\"}]',
  `status` tinyint(4) NULL DEFAULT 1 COMMENT '状态:0-禁用,1-启用',
  `create_user` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `update_user` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` timestamp NULL DEFAULT NULL,
  `update_time` timestamp NULL DEFAULT NULL,
  `model` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '适用于哪个型号的仪器',
  `applicable_countries` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '适用国家',
  `category` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '内置模板0其他模板1',
  `last_used` timestamp NULL DEFAULT NULL COMMENT '最近一次使用时间',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '模板描述',
  `parent_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父模板id',
  `use_count` int(11) NULL DEFAULT 0 COMMENT '使用次数',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `template_code`(`template_code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Excel模板配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of excel_template
-- ----------------------------
INSERT INTO `excel_template` VALUES ('template1690dba4961d44f4b0516c2f6db00e31', 'TEMP_1248071775623221656', '34U1704-01-0023', '[{\"order\": 0, \"dataType\": \"STRING\", \"excelHeader\": \"检测类别\"}, {\"order\": 1, \"dataType\": \"STRING\", \"excelHeader\": \"项目名称\"}, {\"order\": 2, \"dataType\": \"STRING\", \"excelHeader\": \"提示\"}, {\"order\": 3, \"dataType\": \"STRING\", \"excelHeader\": \"方法信息\"}, {\"order\": 4, \"dataType\": \"STRING\", \"excelHeader\": \"测量信息\"}, {\"order\": 5, \"dataType\": \"STRING\", \"excelHeader\": \"重复次数\"}, {\"order\": 6, \"dataType\": \"STRING\", \"excelHeader\": \"重复时间间隔\"}, {\"order\": 7, \"dataType\": \"STRING\", \"excelHeader\": \"特征值\"}, {\"order\": 8, \"dataType\": \"STRING\", \"excelHeader\": \"分析方法\"}, {\"order\": 9, \"dataType\": \"STRING\", \"excelHeader\": \"灯状态\"}, {\"order\": 10, \"dataType\": \"STRING\", \"excelHeader\": \"光度模式\"}, {\"order\": 11, \"dataType\": \"STRING\", \"excelHeader\": \"扫描速度\"}, {\"order\": 12, \"dataType\": \"STRING\", \"excelHeader\": \"起始波长\"}, {\"order\": 13, \"dataType\": \"STRING\", \"excelHeader\": \"终止波长\"}, {\"order\": 14, \"dataType\": \"STRING\", \"excelHeader\": \"扫描间隔\"}, {\"order\": 15, \"dataType\": \"STRING\", \"excelHeader\": \"增益\"}, {\"order\": 16, \"dataType\": \"STRING\", \"excelHeader\": \"光谱带宽\"}, {\"order\": 17, \"dataType\": \"STRING\", \"excelHeader\": \"时间间隔\"}, {\"order\": 18, \"dataType\": \"STRING\", \"excelHeader\": \"扫描个数\"}, {\"order\": 19, \"dataType\": \"STRING\", \"excelHeader\": \"响应时间\"}, {\"order\": 20, \"dataType\": \"STRING\", \"excelHeader\": \"是否为光谱扫描\"}, {\"order\": 21, \"dataType\": \"STRING\", \"excelHeader\": \"暗电流物质\"}, {\"order\": 22, \"dataType\": \"STRING\", \"excelHeader\": \"校零物质\"}, {\"order\": 23, \"dataType\": \"STRING\", \"excelHeader\": \"测量物质\"}, {\"order\": 24, \"dataType\": \"STRING\", \"excelHeader\": \"标准值\"}]', 1, NULL, NULL, '2026-04-08 12:40:21', '2026-04-08 12:40:36', NULL, NULL, '0', '2026-04-08 04:40:37', NULL, NULL, 1);
